        std::cerr << "Directory does not exist or is not writable: " << directory << std::endl;
        return;
    }

    // Ensure directory is a directory (not a file)
    if (!S_ISDIR(dirStat.st_mode)) {
        std::cerr << "Path is not a directory: " << directory << std::endl;
        return;
    }

    // Create the file
    std::ofstream file(fullPath);
    if (!file.is_open()) {
        std::cerr << "Failed to open file: " << fullPath << std::endl;
        return;
    }

    // Write content to the file
    file << content;
    file.close();

    // Set file permissions to be readable and writable only by the owner
    if (chmod(fullPath.c_str(), S_IRUSR | S_IWUSR) != 0) {
        std::cerr << "Failed to set file permissions: " << fullPath << std::endl;
    }
}

